public sealed class ProductClient(HttpClient client)
{
    public async Task<(string Stock, string Price)> LoadAsync(
        int productId, CancellationToken cancellationToken)
    {
        var stockTask = client.GetStringAsync(
            $"stock/{productId}", cancellationToken);
        var priceTask = client.GetStringAsync(
            $"prices/{productId}", cancellationToken);

        await Task.WhenAll(stockTask, priceTask);
        return (await stockTask, await priceTask);
    }
}

