public static async Task CopyUploadAsync(
    Stream upload, string destination, CancellationToken cancellationToken)
{
    await using var output = new FileStream(destination,
        FileMode.CreateNew, FileAccess.Write, FileShare.None,
        bufferSize: 81920, useAsync: true);

    await upload.CopyToAsync(output, cancellationToken);
}

